// Chikiting System - flattens one ticket plus its thread into the single
// block of text the extractor reads.
//
// Doing this here rather than in the prompt keeps the shape stable no matter
// which model answers, and caps the history so a long-running ticket cannot
// grow past the local model's context window.

const HISTORY_LIMIT = 20;

const body = $('Webhook').first().json.body || {};
const t = body.ticket || {};
const history = Array.isArray(body.history) ? body.history : [];

const clean = (v, fallback) => {
  const s = String(v === null || v === undefined ? '' : v).trim();
  return s === '' ? fallback : s;
};

const lines = history.slice(-HISTORY_LIMIT).map((m) => {
  const who = clean(m.author, 'Someone');
  const role = clean(m.role, 'user');
  const said = String(m.body || '').replace(/\s+/g, ' ').trim();
  return `${who} (${role}): ${said}`;
});

const text = [
  'THE TICKET',
  `Reference: #${clean(body.ticket_id, '?')}`,
  `Title: ${clean(t.title, '(none)')}`,
  `Status: ${clean(t.status, 'New')}`,
  `Category: ${clean(t.category, '(none)')}`,
  `Owning team: ${clean(t.responsible_department, clean(t.submitting_department, '(unassigned)'))}`,
  `Priority: ${clean(t.priority, 'Medium')}`,
  `Raised by: ${clean(t.requester, '(unknown)')}`,
  `Current description: ${clean(t.description, '(none)')}`,
  `Original words of the requester: ${clean(t.request_body, '(none)')}`,
  `Expected deliverable: ${clean(t.expected_deliverable, '(none)')}`,
  `Requirements to start: ${clean(t.requirements_needed, '(none)')}`,
  `Closure criteria: ${clean(t.closure_criteria, '(none)')}`,
  '',
  'THE CONVERSATION SO FAR (oldest first)',
  lines.length ? lines.join('\n') : '(nothing yet)',
  '',
  `THE NEW MESSAGE, from ${clean(body.sender_name, 'the requester')} (${clean(body.sender_role, 'requester')})`,
  String(body.message || '').trim()
].join('\n');

return [{ json: { text, use_gemini: String(body.prefer_cloud || 'No') === 'Yes' ? 'Yes' : 'No' } }];

// Chikiting System - turns the model's read of the conversation into a reply
// and, at most, a short list of changes to the ticket.
//
// Everything the model asked for is re-checked here, and again in PHP before
// anything is written. Resolving a ticket is the only destructive action on
// offer, so it needs three things to agree: the model called it resolved, the
// person who raised it sent the message, and the message actually says so.

const STATES = ['OPEN', 'SELF_RESOLVED', 'NEEDS_STAFF'];
const INTENTS = ['NEW_INFO', 'ASK_HELP', 'CONFIRM_RESOLVED', 'CHASE_UPDATE', 'UNRELATED'];
const CONFIRMS = /\b(resolved|resolve|fixed|it works|works now|working now|sorted|solved|done now|no longer needed|not needed|all good|never mind|nevermind)\b/i;

const body = $('Webhook').first().json.body || {};
const ticket = body.ticket || {};
const dept = String(ticket.responsible_department || ticket.submitting_department || '').trim() || 'the assigned team';
const status = String(ticket.status || 'New');
const fromRequester = String(body.sender_is_requester || 'No') === 'Yes';
const message = String(body.message || '');

const results = [];
for (const item of $input.all()) {
  const ai = item.json.output || {};

  let reply = String(ai.reply || '').trim();
  const modelOk = reply !== '';

  let state = String(ai.resolution_state || '').trim().toUpperCase().replace(/[^A-Z_]/g, '');
  if (!STATES.includes(state)) state = 'OPEN';

  let intent = String(ai.intent || '').trim().toUpperCase().replace(/[^A-Z_]/g, '');
  if (!INTENTS.includes(intent)) intent = 'NEW_INFO';

  if (!modelOk) {
    state = 'NEEDS_STAFF';
    reply = `I could not reach my language model just then, so I have not read your message properly - but it is saved on this ticket and ${dept} can see it. If this is urgent, contact them directly.`;
  }

  const confirmed = intent === 'CONFIRM_RESOLVED' || CONFIRMS.test(message);
  const mayResolve = modelOk
    && fromRequester
    && state === 'SELF_RESOLVED'
    && confirmed
    && status !== 'Closed'
    && status !== 'Resolved';

  // Claimed resolved but the guards did not agree: keep it open and say nothing
  // about it, rather than telling the requester it is closed when it is not.
  if (state === 'SELF_RESOLVED' && !mayResolve) state = 'OPEN';

  if (modelOk && state === 'NEEDS_STAFF') {
    reply += `\n\nI cannot finish this one myself - ${dept} owns the next step, and they can see this whole thread on the ticket.`;
  }
  if (mayResolve) {
    reply += '\n\nI have marked this ticket resolved and written up what fixed it. Reply here any time if it comes back.';
  }

  const description = String(ai.updated_description || '').trim();
  const note = String(ai.resolution_note || '').trim();

  results.push({ json: {
    reply,
    intent,
    resolution_state: state,
    can_self_serve: String(ai.can_self_serve || '').trim().toLowerCase().startsWith('y') ? 'Yes' : 'No',
    // Read by TicketAssistant to decide whether this reply is labelled as a
    // suggested fix or as a plain update. A model that skipped the field, or
    // invented a fourth level, is treated as 'medium' - which never on its own
    // earns the suggestion label.
    confidence: ['low', 'medium', 'high'].includes(String(ai.confidence || '').trim().toLowerCase())
      ? String(ai.confidence).trim().toLowerCase()
      : 'medium',
    model_ok: modelOk ? 'Yes' : 'No',
    ai_source: String(item.json.ai_source || 'Local'),
    actions: {
      set_status: mayResolve ? 'Resolved' : '',
      set_description: (description.length >= 20 && description.length <= 2000) ? description : '',
      resolution_note: mayResolve ? note : ''
    }
  } });
}
return results;
